def balanced(text):
    """Return True when the brackets (), [] and {} in *text* are balanced:
    every opening bracket is closed by the matching kind, in the right
    order. All other characters are ignored, including quotes and "<>".

        >>> balanced("f(a[1], {b: 2})")
        True
        >>> balanced("(]")
        False
        >>> balanced("")
        True
    """
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

def _int_to_roman(n):
    """Return the standard Roman numeral for 1 <= n <= 3999."""
    pairs = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ]
    out = []
    for value, symbol in pairs:
        count, n = divmod(n, value)
        out.append(symbol * count)
    return "".join(out)


def roman_to_int(s):
    """Convert an uppercase Roman numeral to an int (1 to 3999).

    Only the standard form is accepted: the one int_to_roman would write,
    using I, V, X, L, C, D, M with the subtractive pairs IV, IX, XL, XC, CD
    and CM.

        >>> roman_to_int("MCMXCIV")
        1994
        >>> roman_to_int("LVIII")
        58

    Raise ValueError for an empty string, lowercase letters or any other
    character, and for non standard forms such as "IIII", "VV", "IC", "IL"
    or "XM".
    """
    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    if not s or any(ch not in values for ch in s):
        raise ValueError(f"invalid Roman numeral: {s!r}")

    total = 0
    for i, ch in enumerate(s):
        value = values[ch]
        if i + 1 < len(s) and value < values[s[i + 1]]:
            total -= value
        else:
            total += value

    if not 1 <= total <= 3999:
        raise ValueError(f"invalid Roman numeral: {s!r}")
    if _int_to_roman(total) != s:
        raise ValueError(f"non standard Roman numeral: {s!r}")
    return total

def balanced(text):
    """Return True when the brackets (), [] and {} in *text* are balanced:
    every opening bracket is closed by the matching kind, in the right
    order. All other characters are ignored, including quotes and "<>".

        >>> balanced("f(a[1], {b: 2})")
        True
        >>> balanced("(]")
        False
        >>> balanced("")
        True
    """
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

_ROMAN_PAIRS = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]

_ROMAN_DIGITS = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def _int_to_roman(n):
    parts = []
    for value, symbol in _ROMAN_PAIRS:
        count, n = divmod(n, value)
        parts.append(symbol * count)
    return "".join(parts)


def roman_to_int(s):
    """Convert an uppercase Roman numeral to an int (1 to 3999).

    Only the standard form is accepted: the one int_to_roman would write,
    using I, V, X, L, C, D, M with the subtractive pairs IV, IX, XL, XC, CD
    and CM.

        >>> roman_to_int("MCMXCIV")
        1994
        >>> roman_to_int("LVIII")
        58

    Raise ValueError for an empty string, lowercase letters or any other
    character, and for non standard forms such as "IIII", "VV", "IC", "IL"
    or "XM".
    """
    if not s:
        raise ValueError("empty Roman numeral")
    if any(ch not in _ROMAN_DIGITS for ch in s):
        raise ValueError(f"invalid Roman numeral: {s!r}")

    total = 0
    for i, ch in enumerate(s):
        value = _ROMAN_DIGITS[ch]
        if i + 1 < len(s) and value < _ROMAN_DIGITS[s[i + 1]]:
            total -= value
        else:
            total += value

    if not 1 <= total <= 3999 or _int_to_roman(total) != s:
        raise ValueError(f"non standard Roman numeral: {s!r}")
    return total

SMALL_WORDS = {"a", "an", "the", "and", "or", "of", "in", "on", "to"}


def _capitalize(word):
    return word[:1].upper() + word[1:].lower()


def title_case(text):
    """Title case a heading.

    Words are split on any run of whitespace and joined by single spaces in
    the result, so leading and trailing whitespace disappears. Each word
    gets its first letter uppercased and the rest lowercased. These small
    words stay all lowercase unless they are the first or the last word:
    a, an, the, and, or, of, in, on, to. In a hyphenated word each part is
    treated like a word of its own, but the small word rule does not apply
    inside it.

        >>> title_case("the lord OF the rings")
        'The Lord of the Rings'
        >>> title_case("  a well-known   tale ")
        'A Well-Known Tale'
        >>> title_case("what to")
        'What To'
    """
    words = text.split()
    last = len(words) - 1
    result = []
    for i, word in enumerate(words):
        if "-" in word:
            result.append("-".join(_capitalize(part) for part in word.split("-")))
        elif 0 < i < last and word.lower() in SMALL_WORDS:
            result.append(word.lower())
        else:
            result.append(_capitalize(word))
    return " ".join(result)
